sys_variable_value.value:
(function execute(inputs, outputs) {
    
    const api = new x_neyu_google_nyu.LicenseAPI();
    const response = api.insert(
        inputs.productId,
        inputs.skuId,
        inputs.userId
    );

    outputs.error = response.error;
    outputs.error_message = "";

    if (response.error) {
        outputs.error_message = response.errorMessage;
    } else if (response.status == 200) {
        outputs.license = JSON.parse(response.responseBody);
    } else {
        outputs.error_response = JSON.parse(response.responseBody);
    }

})(inputs, outputs);

